package local.mediacenter.library

import android.content.Context
import android.net.Uri
import android.provider.DocumentsContract as Documents
import java.io.File
import java.net.ServerSocket
import java.security.MessageDigest
import org.json.*

/** Tests run exclusively in the disposable self-instrumenting APK, with generated bytes. */
internal object TransferLifecycleChecks {
 private val bytes=ByteArray(150000){(it%239).toByte()}
 private val tree=Documents.buildTreeDocumentUri(TransferTestProvider.AUTHORITY,"root")
 private val root=Documents.buildDocumentUriUsingTree(tree,"root")
 private fun prefs(c:Context)=c.getSharedPreferences("media_downloads",Context.MODE_PRIVATE)
 private fun field(name:String,value:Any){OfflineStore.javaClass.getDeclaredField(name).apply{isAccessible=true}.set(OfflineStore,value)}
 private fun reset(c:Context){
  check(c.packageName=="local.mediacenter.library.test")
  TransferTestProvider.denied=false;TransferTestProvider.full=false;TransferTestProvider.renameFails=false
  check(prefs(c).edit().clear().putString("tree",tree.toString()).commit())
  val f=File(c.cacheDir,"transfer-fixture");check(f.canonicalPath.startsWith(c.cacheDir.canonicalPath+File.separator));if(f.exists())check(f.deleteRecursively());check(f.mkdirs())
  field("activeStatus","downloading");field("active","transfer-fixture")
 }
 private fun io(c:Context,title:String="Original",truncated:Boolean=false,pause:Boolean=false):Throwable? {
  val socket=ServerSocket(0,1,java.net.InetAddress.getByName("127.0.0.1"));val thread=Thread{runCatching{
   socket.accept().use{client->client.soTimeout=5000;val reader=client.getInputStream().bufferedReader();while(reader.readLine()?.isNotEmpty()==true){};val output=client.getOutputStream();output.write("HTTP/1.1 200 OK\r\nContent-Type: audio/wav\r\nContent-Length: ${bytes.size}\r\nConnection: close\r\n\r\n".toByteArray());if(pause)field("activeStatus","paused");runCatching{output.write(if(truncated)bytes.copyOf(1000) else bytes);output.flush()}}
  }}.apply{isDaemon=true;start()}
  val t=Playable("transfer-fixture","tone",title,"Generated artist","Generated album","","http://127.0.0.1:${socket.localPort}/original",30.0,suffix="wav")
  return try{
   val method=OfflineStore.javaClass.getDeclaredMethod("runJob",Context::class.java,List::class.java,String::class.java,kotlin.jvm.functions.Function1::class.java).apply{isAccessible=true}
   val resolve:(Playable)->Playable={t};method.invoke(OfflineStore,c,listOf(t),"Generated export",resolve);null
  }catch(e:java.lang.reflect.InvocationTargetException){e.cause}finally{socket.close();thread.join(5000)}
 }
 private fun files(c:Context)=File(c.cacheDir,"transfer-fixture").walkTopDown().filter{it.isFile}.toList()
 private fun record(name:String)=JSONObject().put("key","transfer-fixture:tone").put("account","transfer-fixture").put("id","tone").put("kind","music").put("tree",tree.toString()).put("name",name).put("path","Music/$name").put("bytes",bytes.size).put("sha256",MessageDigest.getInstance("SHA-256").digest(bytes).joinToString(""){"%02x".format(it)}).put("title","Generated original").put("artist","Generated artist").put("album","Generated album").put("duration",30)
 fun run(c:Context,phase:(String)->Unit){
  phase("cold scheduled transfer ownership");reset(c);check(OfflineStore.beginScheduled(c,"generated-owner"));OfflineStore.endScheduled(c,"generated-owner");
  phase("original SAF transfer");reset(c);val first=io(c);check(first==null){first!!.javaClass.simpleName+": "+first.message+" "+first.stackTrace.take(5).joinToString(" | ")};val rows=JSONArray(prefs(c).getString("items","[]"));check(rows.length()==1);val saved=rows.getJSONObject(0);check(c.contentResolver.openInputStream(Uri.parse(saved.getString("uri")))!!.use{it.readBytes()}.contentEquals(bytes));check(files(c).none{it.name.endsWith(".partial")});check(!prefs(c).contains("pendingFile"));check(files(c).any{it.extension=="m3u8"&&it.readText().contains(saved.getString("name"))})
  phase("completed originals are reused");val before=files(c).filter{it.extension=="wav"};check(io(c)==null);check(files(c).filter{it.extension=="wav"}==before)
  phase("explicit legacy export linking and stale refusal");val lists=Documents.buildDocumentUriUsingTree(tree,"root/Playlists");val legacy=Documents.createDocument(c.contentResolver,lists,"audio/x-mpegurl","legacy.m3u8")!!;val legacyBytes=PortablePlaylist.render(listOf("../"+saved.getString("path"),"../"+saved.getString("path"))).toByteArray();c.contentResolver.openOutputStream(legacy)!!.use{it.write(legacyBytes)};val preview=JSONObject(ManagedPlaylists.preview(c,legacy));check(preview.getInt("tracks")==2);check(c.contentResolver.openInputStream(legacy)!!.use{it.readBytes()}.contentEquals(legacyBytes));c.contentResolver.openOutputStream(legacy,"wa")!!.use{it.write("#changed\n".toByteArray())};check(runCatching{ManagedPlaylists.apply(c,preview.getString("token"))}.isFailure);c.contentResolver.openOutputStream(legacy,"wt")!!.use{it.write(legacyBytes)};ManagedPlaylists.apply(c,JSONObject(ManagedPlaylists.preview(c,legacy)).getString("token"))
  phase("external edits block destructive cache removal");val generated=files(c).first{it.extension=="m3u8"&&it.name!="legacy.m3u8"};val priorBytes=generated.readBytes();generated.appendText("#external change\n");check(runCatching{OfflineStore.remove(c,saved.getString("key"))}.isFailure);check(files(c).any{it.extension=="wav"});generated.writeBytes(priorBytes);OfflineStore.remove(c,saved.getString("key"));check(files(c).none{it.extension=="wav"});check(files(c).filter{it.extension=="m3u8"}.all{it.readText()=="#EXTM3U\n"})
  phase("recreate original for integrity acceptance");check(io(c)==null);val checked=JSONArray(prefs(c).getString("items","[]")).getJSONObject(0)
  phase("integrity check preserves damaged originals");File(c.cacheDir,"transfer-fixture/"+checked.getString("path")).appendBytes(byteArrayOf(1));check(OfflineStore.verify(c).contains("1 changed"));check(files(c).any{it.extension=="wav"})
  phase("short HTTP body never becomes cached");reset(c);check(io(c,truncated=true)!=null);check(JSONArray(prefs(c).getString("items","[]")).length()==0);check(files(c).isEmpty());check(!prefs(c).contains("pendingFile"))
  phase("storage write failure preserves library");reset(c);File(c.cacheDir,"transfer-fixture/unrelated.wav").writeText("user owned");TransferTestProvider.full=true;check(io(c)!=null);TransferTestProvider.full=false;check(files(c).map{it.name}==listOf("unrelated.wav"));check(files(c).single().readText()=="user owned");check(!prefs(c).contains("pendingFile"))
  phase("rename failure cleans only owned temporary file");reset(c);TransferTestProvider.renameFails=true;check(io(c)!=null);TransferTestProvider.renameFails=false;check(files(c).isEmpty());check(!prefs(c).contains("pendingFile"))
  phase("pause stops before original commit");reset(c);check(io(c,pause=true)!=null);check(files(c).isEmpty());check(JSONArray(prefs(c).getString("items","[]")).length()==0)
  phase("denied folder access preserves recovery journal");reset(c);val (temp,_)=TransferJournal.begin(c,tree,root,"Generated","wav","audio/wav");c.contentResolver.openOutputStream(temp)!!.use{it.write(bytes)};TransferTestProvider.denied=true;check(runCatching{TransferJournal.recover(c)}.isFailure);check(prefs(c).contains("pendingFile"));TransferTestProvider.denied=false;TransferJournal.recover(c);check(files(c).isEmpty());check(!prefs(c).contains("pendingFile"))
  phase("modified finalized original is preserved for review");reset(c);val (staged,name)=TransferJournal.begin(c,tree,root,"Generated","wav","audio/wav");c.contentResolver.openOutputStream(staged)!!.use{it.write(bytes)};TransferJournal.prepare(c,record(name));val final=Documents.renameDocument(c.contentResolver,staged,name)!!;c.contentResolver.openOutputStream(final,"wa")!!.use{it.write(byteArrayOf(1))};check(runCatching{TransferJournal.recover(c)}.isFailure);check(prefs(c).contains("pendingFile"));check(files(c).single().length()==bytes.size+1L);check(JSONArray(prefs(c).getString("items","[]")).length()==0)
  phase("cleanup generated files");reset(c)
 }
 fun serviceSeed(c:Context){
  reset(c);EncryptedAccounts.write(c,"service-fixture",JSONObject().put("id","service-fixture").put("type","navidrome").put("name","Generated service fixture").put("url","http://127.0.0.1:18547/music").put("username","fixture-user").put("password","fixture-secret").put("allowHttp",true))
  val jobs=JSONArray();for((id,status)in listOf("active" to "paused","paused" to "paused","cancelled" to "cancelled","complete" to "complete"))jobs.put(JSONObject().put("id","service-$id").put("account","service-fixture").put("title","Generated service $id").put("tracks",JSONArray().put("mc-ahead-current")).put("status",status).put("completed",0).put("total",1))
  check(prefs(c).edit().putString("jobs",jobs.toString()).commit());check(c.getSharedPreferences("service_fixture",Context.MODE_PRIVATE).edit().clear().commit())
 }
 fun cold(c:Context,mode:String){
  check(c.packageName=="local.mediacenter.library.test")
  if(mode.startsWith("transfer-seed-")){
   reset(c);val parent=Documents.createDocument(c.contentResolver,root,Documents.Document.MIME_TYPE_DIR,"Music")!!
   val (temp,name)=TransferJournal.begin(c,tree,parent,"Generated","wav","audio/wav");c.contentResolver.openOutputStream(temp)!!.use{it.write(bytes)}
   if(mode.endsWith("final")){TransferJournal.prepare(c,record(name));Documents.renameDocument(c.contentResolver,temp,name)?:error("Test rename failed")}
   return
  }
  TransferJournal.recover(c);check(!prefs(c).contains("pendingFile"));val rows=JSONArray(prefs(c).getString("items","[]"))
  if(mode.endsWith("final")){check(rows.length()==1);check(c.contentResolver.openInputStream(Uri.parse(rows.getJSONObject(0).getString("uri")))!!.use{it.readBytes()}.contentEquals(bytes));check(files(c).single().extension=="wav")}else{check(rows.length()==0&&files(c).isEmpty())}
  reset(c)
 }
}
